  width:0 !important; height:0 !important;
  border-top:6px solid transparent !important; border-bottom:6px solid transparent !important;
  background:none !important; pointer-events:none !important; z-index:1 !important;
}
.bubble-me-custom::after{
  right:-6px !important; left:auto !important;
  border-left:6px solid var(--wx-me) !important; border-right:0 !important;
}
