/* ==========================================================
   4. 时间戳 / 日期 / 撤回  居中方角小框
   ========================================================== */
:is(.timestamp-custom, .date-divider-custom, .msg-recalled .msg-system){
  display:table !important; box-sizing:border-box !important;
  width:auto !important; max-width:80vw !important;
