}
.msg-recalled .msg-system *{ color:var(--wx-chip-ink) !important; }
.msg-status-custom{ color:var(--wx-gray) !important; }

/* ==========================================================
   5. 引用  正文气泡在上 · 浅灰方角引用框在下 · 严格两行
   ========================================================== */
.msg-reply-block{ display:none !important; }
.msg-reply-block-detached{
  display:-webkit-box !important; -webkit-box-orient:vertical !important; -webkit-line-clamp:2 !important;
  position:relative !important; box-sizing:content-box !important;
