.msg-reply-block-detached::before,
.msg-reply-block-detached::after{ content:none !important; }
.msg-reply-block-detached *{
  display:inline !important; margin:0 !important; padding:0 !important;
  font-size:13px !important; line-height:18px !important;
  font-style:normal !important; font-weight:400 !important;
  opacity:1 !important; text-transform:none !important;
  white-space:normal !important; max-width:none !important; overflow:visible !important;
  color:var(--wx-gray-dk) !important; background:transparent !important;
}

