          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.8' stroke-linecap='round'><circle cx='6' cy='12' r='1.3' fill='black' stroke='none'/><path d='M10 8.2a5.4 5.4 0 0 1 0 7.6'/><path d='M13.6 5a9.8 9.8 0 0 1 0 14'/></svg>") no-repeat center/contain;
