          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30' fill='none' stroke='black' stroke-width='1.6' stroke-linecap='round'><circle cx='15' cy='15' r='13.2'/><circle cx='10.2' cy='15' r='1.3' fill='black' stroke='none'/><path d='M13.4 11.6a4.6 4.6 0 0 1 0 6.8'/><path d='M16.4 9a8.4 8.4 0 0 1 0 12'/></svg>") no-repeat center/contain;
}
