.bubble-them-custom :is(span,p,div,a,strong,em):not(.msg-translation-btn):not(.msg-translation-btn *){ color:var(--wx-ink) !important; }

.bubble-them-custom :is(p,span,div):not(.msg-translation-wrapper):not(.msg-translation-btn):not(.msg-translation-btn *),
