/* ==========================================================
   15. 夜间模式  跟随系统深色自动切换(只换颜色变量)
   ========================================================== */
@media (prefers-color-scheme: dark){
  .chat-detail-screen, #chat-detail-screen{
    --wx-bar:      rgba(30,30,30,.98);
    --wx-line:     rgba(255,255,255,.08);
    --wx-me:       #CEECFA;
    --wx-me-ink:   #0D0D0D;
    --wx-ta:       #2C2C2C;
    --wx-ink:      #E5E5E5;
    --wx-gray:     #7A7A7A;
    --wx-gray-dk:  #9A9A9A;
