.chat-detail-screen .chat-header-custom .glass-header::before,
.chat-detail-screen .chat-header-custom .glass-header::after{ display:none !important; }
.chat-detail-screen .chat-header-custom:has(.header-profile-section) .glass-header *:not(.nuo-chat-header-unread-dot):not(.nuo-chat-header-unread-num){
