          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='5' cy='12' r='1.8'/><circle cx='12' cy='12' r='1.8'/><circle cx='19' cy='12' r='1.8'/></svg>") no-repeat center/contain;
}

/* ==========================================================
   2. 头像  38px · 圆角 4px
   ========================================================== */
:is(.msg-avatar-them-container, .msg-avatar-me-container){
  width:var(--wx-avatar) !important; height:var(--wx-avatar) !important;
  min-width:var(--wx-avatar) !important;
  border:0 !important; box-shadow:none !important;
}
:is(.msg-avatar-them-inner, .msg-avatar-me-inner, .msg-avatar-custom){
  width:var(--wx-avatar) !important; height:var(--wx-avatar) !important;
