  border:0 !important; border-radius:var(--wx-avatar-r) !important;
  box-shadow:none !important; overflow:hidden !important;
  object-fit:cover !important; background-size:cover !important; background-position:center !important;
}
:is(.msg-avatar-them-inner, .msg-avatar-me-inner) img{
  width:100% !important; height:100% !important;
  border-radius:var(--wx-avatar-r) !important; object-fit:cover !important;
}

/* ==========================================================
   3. 气泡  方角 4px · 靠头像那侧三角尾巴 · 16/22 字号
   ========================================================== */
.msg-bubble-wrapper{ position:relative !important; }
.bubble-me-custom, .bubble-them-custom,
.bubble-deco-me, .bubble-deco-them,
.msg-bubble-container, .msg-content-stack{ overflow:visible !important; }
.msg-content-stack{ position:relative !important; }

.bubble-them-custom,
.bubble-me-custom{
  position:relative !important; box-sizing:border-box !important;
  max-width:68vw !important;
  padding:7px 12px !important;
  border:0 !important; border-radius:var(--wx-radius) !important;
  box-shadow:none !important; text-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  font-size:16px !important; line-height:22px !important;
}
.bubble-me-custom{ background:var(--wx-me) !important; background-image:none !important; color:var(--wx-me-ink) !important; }
.bubble-them-custom{ background:var(--wx-ta) !important; background-image:none !important; color:var(--wx-ink) !important; }
.bubble-me-custom :is(span,p,div,a,strong,em):not(.msg-translation-btn):not(.msg-translation-btn *){ color:var(--wx-me-ink) !important; }
.bubble-them-custom :is(span,p,div,a,strong,em):not(.msg-translation-btn):not(.msg-translation-btn *){ color:var(--wx-ink) !important; }

.bubble-them-custom :is(p,span,div):not(.msg-translation-wrapper):not(.msg-translation-btn):not(.msg-translation-btn *),
.bubble-me-custom :is(p,span,div):not(.msg-translation-wrapper):not(.msg-translation-btn):not(.msg-translation-btn *){
  max-width:none !important;
}
.bubble-them-custom, .bubble-me-custom,
.bubble-them-custom :is(p,span,div), .bubble-me-custom :is(p,span,div){
