  border:.5px solid var(--wx-chip-line) !important; border-radius:var(--wx-radius) !important;
  -webkit-backdrop-filter:blur(6px) !important; backdrop-filter:blur(6px) !important;
  color:var(--wx-chip-ink) !important; opacity:1 !important;
  font-size:13px !important; line-height:16px !important; font-weight:700 !important;
  letter-spacing:.02em !important; text-align:center !important; white-space:nowrap !important;
}
