.msg-status-custom{ color:var(--wx-gray) !important; }

/* ==========================================================
   5. 引用  正文气泡在上 · 浅灰方角引用框在下 · 严格两行
   ========================================================== */
.msg-reply-block{ display:none !important; }
.msg-reply-block-detached{
  display:-webkit-box !important; -webkit-box-orient:vertical !important; -webkit-line-clamp:2 !important;
  position:relative !important; box-sizing:content-box !important;
  width:max-content !important; min-width:0 !important; max-width:calc(60vw - 18px) !important;
  height:auto !important; max-height:36px !important;
  margin:6px 0 0 0 !important; padding:0 9px !important;
  background:var(--wx-quote) !important;
  border:0 !important; border-left:0 !important;
  border-top:6px solid var(--wx-quote) !important; border-bottom:6px solid var(--wx-quote) !important;
  border-radius:var(--wx-radius) !important;
  box-shadow:0 0 0 .5px var(--wx-quote-line) !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  transform:none !important; clip-path:none !important; opacity:1 !important;
  font-size:13px !important; line-height:18px !important; color:var(--wx-gray-dk) !important;
  white-space:normal !important; word-break:break-word !important; overflow:hidden !important;
