/* ==========================================================
   1. 顶栏  独立磨砂背板(只透颜色) · 头像/在线隐藏 · 昵称居中
            退出=返回箭头 / 设置=三个点 / 电话·视频=隐形原位可点
            AI 回复中:昵称换成"对方正在输入中..."
   ========================================================== */
/* 顶栏本身不涂色,颜色和模糊交给下面的背板 */
.chat-detail-screen :is(.chat-header-custom, .glass-header):has(.header-profile-section){
  background:transparent !important; background-image:none !important;
  -webkit-backdrop-filter:none !important; backdrop-filter:none !important;
  border:0 !important; box-shadow:none !important;
  min-height:var(--wx-head-h) !important;
}
/* 磨砂背板 */
.chat-detail-screen .chat-header-custom:has(.header-profile-section)::before{
  content:"" !important; display:block !important;
  position:absolute !important; inset:0 !important;
  background:var(--wx-bar) !important;
  -webkit-backdrop-filter:var(--wx-blur) !important; backdrop-filter:var(--wx-blur) !important;
  border-bottom:.5px solid var(--wx-line) !important;
  pointer-events:none !important; z-index:-1 !important;
}
.chat-detail-screen .chat-header-custom:has(.header-profile-section)::after{ content:none !important; }
/* 内层(嵌套时)透明 */
.chat-detail-screen .chat-header-custom .glass-header{
  position:relative !important;
  background:transparent !important;
  -webkit-backdrop-filter:none !important; backdrop-filter:none !important;
  border:0 !important;
}
.chat-detail-screen .chat-header-custom .glass-header::before,
.chat-detail-screen .chat-header-custom .glass-header::after{ display:none !important; }
.chat-detail-screen .chat-header-custom:has(.header-profile-section) .glass-header *:not(.nuo-chat-header-unread-dot):not(.nuo-chat-header-unread-num){
  background-color:transparent !important;
}

.chat-detail-screen .header-avatar-container,
.chat-detail-screen .chat-header-custom .chat-header-avatar,
.chat-detail-screen .chat-header-subtitle{ display:none !important; }

.chat-detail-screen .header-profile-section{
  position:absolute !important;
  left:50% !important; top:auto !important; bottom:calc(var(--wx-head-h) / 2) !important;
  transform:translate(-50%, 50%) !important;
  margin:0 !important; padding:0 !important;
  display:flex !important; align-items:center !important; justify-content:center !important;
  max-width:60vw !important; background:transparent !important; z-index:5 !important;
}
.chat-detail-screen .header-profile-section > *{ margin:0 !important; }
.chat-detail-screen .header-profile-section::before,
.chat-detail-screen .header-profile-section::after{ content:none !important; }
.chat-detail-screen .chat-header-custom .chat-header-title{
  margin:0 !important; padding:0 !important; max-width:60vw !important;
  background:transparent !important; border:0 !important; text-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  color:var(--wx-ink) !important; font-size:17px !important; font-weight:600 !important;
  line-height:1 !important; text-align:center !important;
  white-space:nowrap !important; overflow:hidden !important; text-overflow:ellipsis !important;
}
.chat-detail-screen .chat-header-custom .chat-header-title::before,
.chat-detail-screen .chat-header-custom .chat-header-title::after{ content:none !important; }

.chat-detail-screen .nuo-typing-indicator{ display:none !important; }
.chat-detail-screen .msg-bubble-wrapper:has(.msg-streaming){ display:none !important; }
#chat-detail-screen:has(.nuo-typing-indicator, .msg-streaming) .chat-header-custom .chat-header-title,
.chat-detail-screen:has(.nuo-typing-indicator, .msg-streaming) .chat-header-custom .chat-header-title{
  font-size:0 !important; color:transparent !important;
}
#chat-detail-screen:has(.nuo-typing-indicator, .msg-streaming) .chat-header-custom .chat-header-title::after,
.chat-detail-screen:has(.nuo-typing-indicator, .msg-streaming) .chat-header-custom .chat-header-title::after{
  content:"对方正在输入中..." !important;
  font-size:17px; font-weight:600; line-height:1; color:var(--wx-ink); white-space:nowrap;
}

.chat-detail-screen :is(.header-btn-back, .header-btn-info, .header-btn-phone, .header-btn-video){
  position:relative !important;
  width:36px !important; height:36px !important; min-width:36px !important;
  padding:0 !important; border-radius:0 !important;
  display:flex !important; align-items:center !important; justify-content:center !important;
  background:transparent !important; background-image:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  border:0 !important; box-shadow:none !important;
  color:transparent !important; overflow:visible !important; z-index:6 !important;
