.chat-detail-screen :is(.header-btn-phone, .header-btn-video)::before,
.chat-detail-screen :is(.header-btn-phone, .header-btn-video)::after,
.chat-detail-screen :is(.header-btn-back, .header-btn-info)::after{ content:none !important; }
.chat-detail-screen :is(.header-btn-back, .header-btn-info)::before{
  content:"" !important; position:absolute; top:50%; left:50%; transform:translate(-50%,-50%);
  background-color:var(--wx-ink); pointer-events:none;
}
.chat-detail-screen .header-btn-back::before{
  width:22px; height:22px;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.4' stroke-linecap='round' stroke-linejoin='round'><polyline points='15 4 7 12 15 20'/></svg>") no-repeat center/contain;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.4' stroke-linecap='round' stroke-linejoin='round'><polyline points='15 4 7 12 15 20'/></svg>") no-repeat center/contain;
}
.chat-detail-screen .header-btn-info::before{
  width:24px; height:24px;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='5' cy='12' r='1.8'/><circle cx='12' cy='12' r='1.8'/><circle cx='19' cy='12' r='1.8'/></svg>") no-repeat center/contain;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='5' cy='12' r='1.8'/><circle cx='12' cy='12' r='1.8'/><circle cx='19' cy='12' r='1.8'/></svg>") no-repeat center/contain;
}

/* ==========================================================
   2. 头像  38px · 圆角 4px
   ========================================================== */
:is(.msg-avatar-them-container, .msg-avatar-me-container){
  width:var(--wx-avatar) !important; height:var(--wx-avatar) !important;
