  width:100% !important; height:100% !important;
  border-radius:var(--wx-avatar-r) !important; object-fit:cover !important;
}

/* ==========================================================
   3. 气泡  方角 4px · 靠头像那侧三角尾巴 · 16/22 字号
   ========================================================== */
.msg-bubble-wrapper{ position:relative !important; }
.bubble-me-custom, .bubble-them-custom,
.bubble-deco-me, .bubble-deco-them,
.msg-bubble-container, .msg-content-stack{ overflow:visible !important; }
