          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 17 5' shape-rendering='crispEdges'><rect x='1' y='0' width='1' height='5'/><rect x='0' y='1' width='1' height='1'/><rect x='0' y='4' width='3' height='1'/><rect x='4' y='0' width='3' height='1'/><rect x='4' y='2' width='3' height='1'/><rect x='4' y='4' width='3' height='1'/><rect x='6' y='0' width='1' height='5'/><rect x='8' y='1' width='1' height='1'/><rect x='8' y='3' width='1' height='1'/><rect x='11' y='0' width='1' height='5'/><rect x='10' y='1' width='1' height='1'/><rect x='10' y='4' width='3' height='1'/><rect x='14' y='0' width='1' height='3'/><rect x='16' y='0' width='1' height='5'/><rect x='14' y='2' width='3' height='1'/></svg>") no-repeat center/100% 100%;
