  min-width:var(--wx-btn) !important; max-width:var(--wx-btn) !important;
  min-height:var(--wx-btn) !important; max-height:var(--wx-btn) !important;
  padding:0 !important; margin:0 !important;
  border:0 !important; border-radius:50% !important;
  background:transparent !important; background-image:none !important;
  box-shadow:none !important; color:transparent !important; opacity:1 !important;
  transform:none !important; filter:none !important;
}
.chat-detail-screen .input-area-custom :is(.input-btn-plus, .input-btn-sticker, .input-btn-ai) > *{ opacity:0 !important; }
.chat-detail-screen .input-area-custom :is(.input-btn-plus, .input-btn-sticker, .input-btn-ai)::after{
  content:"" !important; position:absolute; inset:0; background-color:var(--wx-ink); pointer-events:none;
}
.chat-detail-screen .input-area-custom :is(.input-btn-sticker, .input-btn-ai){ margin-left:8px !important; }
.chat-detail-screen .input-area-custom .input-btn-plus::after{
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30' fill='none' stroke='black' stroke-width='1.6' stroke-linecap='round'><circle cx='15' cy='15' r='13.2'/><circle cx='10.2' cy='15' r='1.3' fill='black' stroke='none'/><path d='M13.4 11.6a4.6 4.6 0 0 1 0 6.8'/><path d='M16.4 9a8.4 8.4 0 0 1 0 12'/></svg>") no-repeat center/contain;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30' fill='none' stroke='black' stroke-width='1.6' stroke-linecap='round'><circle cx='15' cy='15' r='13.2'/><circle cx='10.2' cy='15' r='1.3' fill='black' stroke='none'/><path d='M13.4 11.6a4.6 4.6 0 0 1 0 6.8'/><path d='M16.4 9a8.4 8.4 0 0 1 0 12'/></svg>") no-repeat center/contain;
